<script setup>
import { computed, onMounted, ref } from 'vue'
import { api, getApiError } from '../../api/client'
import { useAuthStore } from '../../stores/auth'
const auth=useAuthStore();const data=ref(null);const loading=ref(true);const error=ref('');const children=computed(()=>data.value?.children||[]);const profile=computed(()=>data.value?.profile||{});const firstName=computed(()=>profile.value.first_name||auth.user?.first_name||'there');
async function load(){loading.value=true;error.value='';try{data.value=(await api.get('/parent-portal/me')).data}catch(e){error.value=getApiError(e,'Unable to load your parent portal.')}finally{loading.value=false}}onMounted(load)
</script>
<template><div class="dashboard-page role-dashboard"><div v-if="loading" class="dashboard-loading"><div class="spinner-border text-primary"></div><span>Loading your parent portal...</span></div><template v-else><section class="dashboard-heading"><div><div class="eyebrow">PARENT PORTAL</div><h1>Good day, {{firstName}} <span class="wave">👋</span></h1><p>Stay connected to your children's school journey.</p></div><div class="heading-actions"><span class="role-badge"><i class="bi bi-person-hearts me-2"></i>Parent account</span></div></section><div v-if="error" class="alert alert-danger border-0 shadow-sm mb-4"><i class="bi bi-exclamation-circle me-2"></i>{{error}}</div><template v-if="!error"><section class="welcome-banner parent-banner mb-4"><div class="welcome-copy"><div class="banner-label"><i class="bi bi-people-fill me-2"></i>MY FAMILY</div><h2>{{children.length}} {{children.length===1?'child':'children'}} linked</h2><p>View the learners connected to your parent account.</p></div><div class="welcome-art"><i class="bi bi-people-fill"></i></div></section><section class="metric-grid mb-4"><div class="metric-card"><div class="metric-icon"><i class="bi bi-people"></i></div><div><span>My Children</span><strong>{{children.length}}</strong><small>Linked to this account</small></div></div><div class="metric-card"><div class="metric-icon"><i class="bi bi-person-check"></i></div><div><span>Active</span><strong>{{children.filter(c=>c.status==='active').length}}</strong><small>Currently active</small></div></div><div class="metric-card"><div class="metric-icon"><i class="bi bi-envelope"></i></div><div><span>Email</span><strong class="metric-value">{{profile.email||'—'}}</strong><small>Portal contact</small></div></div><div class="metric-card"><div class="metric-icon"><i class="bi bi-telephone"></i></div><div><span>Phone</span><strong>{{profile.phone||'—'}}</strong><small>Registered contact</small></div></div></section><div class="row g-4"><div class="col-xl-8"><section class="dashboard-card h-100"><div class="card-heading"><div><h2>My Children</h2><p>Only children linked to your parent account are shown.</p></div></div><div v-if="!children.length" class="empty-state py-5"><i class="bi bi-person-x"></i><h3>No children linked</h3><p>Please contact your school if a child is missing.</p></div><div v-else class="row g-3"><div v-for="child in children" :key="child.id" class="col-md-6"><div class="child-card"><div class="mini-avatar">{{child.first_name?.[0]}}{{child.last_name?.[0]}}</div><div class="flex-grow-1"><strong>{{child.first_name}} {{child.middle_name||''}} {{child.last_name}}</strong><small>{{child.admission_number}}</small><small v-if="child.enrollment?.class">{{child.enrollment.class.name}}{{child.enrollment.stream?.name?' · '+child.enrollment.stream.name:''}}</small></div><span class="badge text-bg-success text-capitalize">{{child.status}}</span></div></div></div></section></div><div class="col-xl-4"><section class="dashboard-card h-100"><div class="card-heading"><div><h2>Parent services</h2><p>School services.</p></div></div><div class="parent-service"><span><i class="bi bi-wallet2"></i></span><div><strong>Fees & Payments</strong><small>Coming soon</small></div><i class="bi bi-lock text-muted"></i></div><div class="parent-service"><span><i class="bi bi-calendar-check"></i></span><div><strong>Attendance</strong><small>Coming soon</small></div><i class="bi bi-lock text-muted"></i></div><div class="parent-service"><span><i class="bi bi-journal-check"></i></span><div><strong>Academic Progress</strong><small>Coming soon</small></div><i class="bi bi-lock text-muted"></i></div><div class="parent-service"><span><i class="bi bi-chat-square-text"></i></span><div><strong>School Communication</strong><small>Coming soon</small></div><i class="bi bi-lock text-muted"></i></div></section></div></div><section class="dashboard-footer mt-4"><div><i class="bi bi-shield-check"></i><span><strong>Private parent workspace</strong><small>You can only access children linked to your own parent account.</small></span></div><router-link to="/school/portal">My Portal <i class="bi bi-arrow-right ms-1"></i></router-link></section></template></template></div></template><style scoped>.role-badge{display:inline-flex;align-items:center;padding:.65rem .9rem;border:1px solid #dce8fb;background:#f8fbff;border-radius:.7rem;color:#0d6efd;font-weight:600}.child-card{display:flex;align-items:center;gap:.8rem;border:1px solid #e9ecef;border-radius:.8rem;padding:1rem;height:100%}.child-card>div:nth-child(2){display:flex;flex-direction:column;min-width:0}.child-card small{color:#6c757d;margin-top:.2rem}.parent-service{display:flex;align-items:center;gap:.8rem;padding:1rem 0;border-bottom:1px solid #edf0f3}.parent-service:last-child{border-bottom:0}.parent-service>span{width:40px;height:40px;border-radius:.65rem;background:#eef5ff;color:#0d6efd;display:flex;align-items:center;justify-content:center}.parent-service>div{display:flex;flex-direction:column;flex:1}.parent-service small{color:#6c757d}.parent-banner .welcome-art{opacity:.25}.metric-value{font-size:1rem!important;word-break:break-word}</style>